inline bool controller_pico_route(std::string_view resource,std::string_view method) {
  if(method=="GET") return resource=="management" || resource=="configuration" || resource=="application" || resource=="station" || resource=="hardware" || resource=="pins" || resource=="gpio-drive" || resource=="gpio-drive-progress" || resource=="amplifier-timing" || resource=="filter-selector" || resource=="si5351" || resource=="gps" || resource=="gray-line" || resource=="progress" || resource=="udp-logging" || resource=="udp-logging/capabilities" || resource=="udp-logging/test/capabilities" || resource=="wifi" || resource=="hostname" || resource=="logging" || resource=="network";
  if(method=="PUT") return resource=="station" || resource=="hardware" || resource=="gpio-drive" || resource=="gpio-drive-progress" || resource=="amplifier-timing" || resource=="filter-selector" || resource=="gray-line" || resource=="udp-logging" || resource=="wifi" || resource=="hostname" || resource=="logging" || resource=="network";
  if(method=="POST") return resource=="management" || resource=="configuration" || resource=="pins/validate" || resource=="gpio-drive-progress" || resource=="progress/update" || resource=="progress/apply" || resource=="udp-logging/test" || resource=="restart" || resource=="ap";
  if(method=="DELETE") return resource=="wifi";
  return false;
}
inline std::string_view controller_pico_recovery_read(std::string_view resource) {
  if(resource=="amplifier-timing") return "amplifier-timing";
  if(resource=="ap") return "hostname";
  if(resource=="configuration") return "configuration";
  if(resource=="filter-selector") return "filter-selector";
  if(resource=="gpio-drive") return "gpio-drive";
  if(resource=="gpio-drive-progress") return "gpio-drive-progress";
  if(resource=="gray-line") return "gray-line";
  if(resource=="hardware") return "hardware";
  if(resource=="hostname") return "hostname";
  if(resource=="logging") return "logging";
  if(resource=="progress/apply") return "progress";
  if(resource=="progress/update") return "progress";
  if(resource=="restart") return "hostname";
  if(resource=="station") return "station";
  if(resource=="udp-logging") return "udp-logging";
  if(resource=="udp-logging/test") return "udp-logging";
  if(resource=="wifi") return "wifi";
  if(resource=="network") return "network";
  return {};
}
